import { test, expect } from '@playwright/test';

test.describe('Success Toast Notification After Saving Record', () => {
  let page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');

    // Wait for the page to load
    await page.waitForLoadState('networkidle');
  });

  test('should display success toast notification when saving a new record', async () => {
    // Navigate to the form or record creation page
    const createButton = page.getByRole('button', { name: /create new/i });
    await createButton.click();

    // Wait for form to appear
    await page.waitForSelector('form');

    // Fill in the form fields
    const nameInput = page.getByLabel(/name/i);
    await nameInput.fill('Test Record');

    const emailInput = page.getByLabel(/email/i);
    await emailInput.fill('test@example.com');

    const descriptionInput = page.getByLabel(/description/i);
    await descriptionInput.fill('This is a test record');

    // Click the save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Wait for and verify the success toast notification appears
    const successToast = page.getByRole('status').filter({ hasText: /success|saved|created/i });
    await expect(successToast).toBeVisible();

    // Verify the toast contains the expected message
    await expect(successToast).toContainText(/record.*saved|successfully.*saved|created.*successfully/i);

    // Verify the toast has the correct styling (success class/color)
    const toastElement = page.locator('[role="status"]').filter({ hasText: /success|saved|created/i }).first();
    const toastClass = await toastElement.getAttribute('class');
    expect(toastClass).toContain('success');
  });

  test('should display success toast notification when updating an existing record', async () => {
    // Navigate to an existing record
    const recordLink = page.getByRole('link', { name: /edit record/i }).first();
    await recordLink.click();

    // Wait for the form to load
    await page.waitForSelector('form');

    // Modify a field
    const nameInput = page.getByLabel(/name/i);
    await nameInput.clear();
    await nameInput.fill('Updated Record Name');

    // Click the save button
    const saveButton = page.getByRole('button', { name: /save|update/i });
    await saveButton.click();

    // Wait for and verify the success toast notification appears
    const successToast = page.getByRole('status').filter({ hasText: /success|updated|saved/i });
    await expect(successToast).toBeVisible();

    // Verify the toast message indicates an update
    await expect(successToast).toContainText(/updated.*successfully|record.*updated|changes.*saved/i);

    // Verify the toast auto-dismisses after a reasonable time (default 5 seconds)
    await expect(successToast).toBeHidden({ timeout: 6000 });
  });

  test('should display success toast with correct positioning and styling', async () => {
    // Create a new record to trigger the toast
    const createButton = page.getByRole('button', { name: /create new/i });
    await createButton.click();

    // Fill and submit the form
    const nameInput = page.getByLabel(/name/i);
    await nameInput.fill('Positioning Test Record');

    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Get the toast element
    const successToast = page.getByRole('status').filter({ hasText: /success|saved/i });
    await expect(successToast).toBeVisible();

    // Verify the toast is positioned correctly (typically top-right or bottom-right)
    const boundingBox = await successToast.boundingBox();
    expect(boundingBox).not.toBeNull();
    expect(boundingBox?.x).toBeGreaterThan(0);
    expect(boundingBox?.y).toBeGreaterThan(0);

    // Verify the toast has appropriate styling
    const backgroundColor = await successToast.evaluate((el) => 
      window.getComputedStyle(el).backgroundColor
    );
    // Success toasts typically have green background
    expect(backgroundColor).toMatch(/rgb\(|rgba\(/);

    // Verify the toast has an icon or indicator
    const toastIcon = successToast.getByRole('img', { hidden: true }).or(
      successToast.locator('svg')
    );
    const iconExists = await toastIcon.count().catch(() => 0);
    expect(iconExists).toBeGreaterThanOrEqual(0);
  });

  test('should handle multiple success toasts when saving multiple records', async () => {
    // Create first record
    let createButton = page.getByRole('button', { name: /create new/i });
    await createButton.click();

    let nameInput = page.getByLabel(/name/i);
    await nameInput.fill('First Record');

    let saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify first toast appears
    let successToast = page.getByRole('status').filter({ hasText: /success|saved/i }).first();
    await expect(successToast).toBeVisible();

    // Wait for first toast to dismiss
    await page.waitForTimeout(1000);

    // Create second record
    createButton = page.getByRole('button', { name: /create new/i });
    await createButton.click();

    nameInput = page.getByLabel(/name/i);
    await nameInput.fill('Second Record');

    saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify second toast appears
    successToast = page.getByRole('status').filter({ hasText: /success|saved/i }).first();
    await expect(successToast).toBeVisible();

    // Verify the toast message is for the second record
    await expect(successToast).toContainText(/success|saved/i);
  });

  test('should not display success toast when save operation fails', async () => {
    // Navigate to form
    const createButton = page.getByRole('button', { name: /create new/i });
    await createButton.click();

    // Leave required fields empty to trigger validation error
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify no success toast appears
    const successToast = page.getByRole('status').filter({ hasText: /success|saved/i });
    await expect(successToast).not.toBeVisible();

    // Verify error message or validation error appears instead
    const errorMessage = page.getByRole('alert').or(
      page.getByText(/required|error|invalid/i)
    );
    const errorExists = await errorMessage.count().catch(() => 0);
    expect(errorExists).toBeGreaterThan(0);
  });
});
